layer.css:
[data-ryt="pitch"] { color: #6d6d6d; border-left: 5px solid rgb(226, 226, 226); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.222; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(51, 51, 51); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 10px; padding-right: 20px; padding-bottom: 10px; padding-left: 20px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-bottom: 1px solid var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="hero"] h1 { color: rgb(71, 190, 199); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1; letter-spacing: 1px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: rgb(71, 190, 199); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: rgb(71, 190, 199); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: 1; letter-spacing: 1px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: rgb(71, 190, 199); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: rgb(71, 190, 199); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1; letter-spacing: 1px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: rgb(71, 190, 199); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(71, 190, 199); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1; letter-spacing: 1px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: rgb(71, 190, 199); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: rgb(202, 72, 109); border-bottom-width: 1px; border-bottom-style: solid; border-bottom-color: rgb(202, 72, 109) }
